create extension if not exists "pgcrypto";

create type public.app_role as enum ('admin','production','quality','inventory','sales_finance');
create type public.stock_status as enum ('available','reserved','quarantine','blocked','expired','in_process');
create type public.production_status as enum ('draft','waiting_materials','planned','scheduled','released','in_production','curing','quality','completed','cancelled');
create type public.movement_type as enum ('purchase','production_consumption','production_output','sale','loss','return','inventory','transfer','adjustment','reversal');

create table public.profiles (id uuid primary key references auth.users on delete cascade, full_name text not null, role public.app_role not null default 'admin', active boolean not null default true, created_at timestamptz not null default now());
create table public.settings (id uuid primary key default gen_random_uuid(), key text unique not null, value jsonb not null, updated_at timestamptz not null default now());
create table public.audit_log (id bigint generated always as identity primary key, actor_id uuid references public.profiles, entity_type text not null, entity_id uuid, action text not null, before_data jsonb, after_data jsonb, created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, phone text, email text, city text, source text, notes text, created_at timestamptz not null default now());
create table public.leads (id uuid primary key default gen_random_uuid(), name text, email text, phone text, interests text[], consent_at timestamptz not null, created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, kind text not null check(kind in ('product','material','packaging')));
create table public.products (id uuid primary key default gen_random_uuid(), sku text unique not null, name text not null, description text, category_id uuid references public.categories, sale_price numeric(12,2) not null default 0, weight_g numeric(10,2), active boolean not null default true, created_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products, sku text unique not null, attributes jsonb not null default '{}', sale_price numeric(12,2), active boolean not null default true);
create table public.recipe_versions (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products, version integer not null, yield_quantity numeric(12,3) not null, instructions text, active boolean not null default true, created_at timestamptz not null default now(), unique(product_id,version));
create table public.items (id uuid primary key default gen_random_uuid(), sku text unique not null, name text not null, kind text not null check(kind in ('material','packaging','finished_good','wip')), unit text not null, minimum_stock numeric(12,3) not null default 0, average_cost numeric(12,4) not null default 0, active boolean not null default true);
create table public.recipe_components (id uuid primary key default gen_random_uuid(), recipe_version_id uuid not null references public.recipe_versions on delete cascade, item_id uuid not null references public.items, quantity numeric(12,4) not null check(quantity>0));
create table public.locations (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, parent_id uuid references public.locations, capacity numeric(12,3), active boolean not null default true);
create table public.stock_lots (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.items, lot_code text not null, expiry_date date, status public.stock_status not null default 'available', unit_cost numeric(12,4) not null default 0, created_at timestamptz not null default now(), unique(item_id,lot_code));
create table public.stock_balances (id uuid primary key default gen_random_uuid(), lot_id uuid not null references public.stock_lots, location_id uuid not null references public.locations, quantity numeric(12,3) not null default 0 check(quantity>=0), reserved_quantity numeric(12,3) not null default 0 check(reserved_quantity>=0), unique(lot_id,location_id), check(quantity>=reserved_quantity));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), item_id uuid not null references public.items, lot_id uuid references public.stock_lots, from_location_id uuid references public.locations, to_location_id uuid references public.locations, movement_type public.movement_type not null, quantity numeric(12,3) not null check(quantity>0), unit_cost numeric(12,4), reason text, source_type text, source_id uuid, performed_by uuid references public.profiles, created_at timestamptz not null default now());
create table public.suppliers (id uuid primary key default gen_random_uuid(), name text not null, document text, email text, phone text, lead_time_days integer, active boolean not null default true);
create table public.purchase_orders (id uuid primary key default gen_random_uuid(), number text unique not null, supplier_id uuid references public.suppliers, status text not null default 'draft', expected_at date, notes text, created_at timestamptz not null default now());
create table public.production_orders (id uuid primary key default gen_random_uuid(), number text unique not null, product_variant_id uuid references public.product_variants, recipe_version_id uuid references public.recipe_versions, quantity_planned numeric(12,3) not null check(quantity_planned>0), quantity_completed numeric(12,3) not null default 0, status public.production_status not null default 'draft', priority text not null default 'normal', due_date date, scheduled_at timestamptz, source text not null, notes text, created_at timestamptz not null default now());
create table public.production_lots (id uuid primary key default gen_random_uuid(), production_order_id uuid not null references public.production_orders, code text unique not null, status public.production_status not null default 'in_production', quantity numeric(12,3) not null, actual_cost numeric(12,4) not null default 0, curing_until timestamptz, created_at timestamptz not null default now());
create table public.quality_inspections (id uuid primary key default gen_random_uuid(), production_lot_id uuid not null references public.production_lots, plan_version integer not null, result text not null check(result in ('pending','approved','quarantine','rejected')), measurements jsonb not null default '{}', inspector_id uuid references public.profiles, created_at timestamptz not null default now());
create table public.sales_orders (id uuid primary key default gen_random_uuid(), number text unique not null, customer_id uuid references public.customers, channel text not null, status text not null default 'received', subtotal numeric(12,2) not null default 0, discount numeric(12,2) not null default 0, shipping numeric(12,2) not null default 0, fees numeric(12,2) not null default 0, total numeric(12,2) not null default 0, created_at timestamptz not null default now());
create table public.financial_entries (id uuid primary key default gen_random_uuid(), type text not null check(type in ('income','expense')), category text not null, amount numeric(12,2) not null check(amount>0), due_date date, paid_at date, source_type text, source_id uuid, notes text, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.settings enable row level security; alter table public.audit_log enable row level security; alter table public.customers enable row level security; alter table public.leads enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.recipe_versions enable row level security; alter table public.items enable row level security; alter table public.recipe_components enable row level security; alter table public.locations enable row level security; alter table public.stock_lots enable row level security; alter table public.stock_balances enable row level security; alter table public.stock_movements enable row level security; alter table public.suppliers enable row level security; alter table public.purchase_orders enable row level security; alter table public.production_orders enable row level security; alter table public.production_lots enable row level security; alter table public.quality_inspections enable row level security; alter table public.sales_orders enable row level security; alter table public.financial_entries enable row level security;
create function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and active)$$;
create policy "staff access" on public.profiles for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.settings for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.audit_log for select using (public.is_staff());
create policy "staff access" on public.customers for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.leads for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.categories for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.products for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.product_variants for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.recipe_versions for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.items for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.recipe_components for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.locations for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.stock_lots for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.stock_balances for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.stock_movements for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.suppliers for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.purchase_orders for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.production_orders for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.production_lots for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.quality_inspections for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.sales_orders for all using (public.is_staff()) with check (public.is_staff());
create policy "staff access" on public.financial_entries for all using (public.is_staff()) with check (public.is_staff());

create policy "Public can submit consented leads" on public.leads for insert with check (consent_at is not null);
insert into storage.buckets (id, name, public) values ('product-images','product-images',false),('quality-evidence','quality-evidence',false),('label-assets','label-assets',false) on conflict (id) do nothing;
